class ExplorationController:
    """Open root once, then refine leaves on the best-scoring lineage first."""
    def __init__(self):
        self.best_id = None
        self.best_score = 0.0
        self.prev_best = 0.0
        self.stalled_rounds = 0
        self.root_opened = False

    def select(self, observed_nodes, round_index, workers, max_depth):
        if not observed_nodes:
            return []
        nodes = {}
        for node in observed_nodes:
            nid = node.get("id")
            if nid is not None:
                nodes[nid] = node
        if 0 not in nodes:
            return []
        # Parent set identifies internal nodes (they already have a child).
        parents = set()
        for node in observed_nodes:
            nid = node.get("id")
            if nid is None or nid == 0:
                continue
            p = node.get("parent")
            if p is not None:
                parents.add(p)
        # Track best revealed nonroot score across calls.
        for node in observed_nodes:
            nid = node.get("id")
            if nid is None or nid == 0:
                continue
            score = node.get("score")
            if score is None:
                continue
            if self.best_id is None or score > self.best_score:
                self.best_score = score
                self.best_id = nid
        if self.best_score > self.prev_best + 1e-15:
            self.prev_best = self.best_score
            self.stalled_rounds = 0
        else:
            self.stalled_rounds += 1
        # Legal leaves: nonroot, no child in observed set, depth < max_depth.
        leaves = []
        for node in observed_nodes:
            nid = node.get("id")
            if nid is None or nid == 0:
                continue
            if nid in parents:
                continue
            if node.get("depth", 0) >= max_depth:
                continue
            leaves.append(nid)

        def path_of(nid):
            path = []
            cur = nid
            seen = set()
            while cur is not None and cur in nodes and cur not in seen:
                seen.add(cur)
                path.append(cur)
                cur = nodes[cur].get("parent")
            return path

        def key(nid):
            node = nodes[nid]
            path = path_of(nid)
            on_best = 0 if (self.best_id is not None and self.best_id in path) else 1
            score = node.get("score")
            if score is None:
                score = -1e18
            st = node.get("stagnation") or 0
            fs = node.get("failure_streak") or 0
            depth = node.get("depth", 0)
            return (on_best, st, fs, -score, -depth, nid)

        leaves.sort(key=key)
        batch = []
        seen_ids = set()
        for nid in leaves[:max(0, workers)]:
            if nid not in seen_ids:
                seen_ids.add(nid)
                batch.append(nid)
        root_exhausted = bool(nodes[0].get("exhausted", False))
        # Open root once early to establish an initial branch, then stay on
        # the productive lineage.  Reopen only when the batch cannot be
        # filled from legal leaves (no productive leaves remain).
        if not root_exhausted and 0 not in seen_ids:
            if not self.root_opened or len(batch) < workers:
                batch.append(0)
                seen_ids.add(0)
                self.root_opened = True
        return batch
